import shp from 'shpjs'
import write from '@mapbox/shp-write/src/write.js'
import dbf from 'dbf'
import JSZip from 'jszip'
import proj4 from 'proj4'
import { coordEach } from '@turf/meta'
import { joinKey } from './csvGeoJsonMerger.js'

/**
 * Read each .shp/.dbf layer in a ZIP, using .prj for WGS84 reprojection and .cpg
 * for text encoding. Each layer retains its filename and becomes a FeatureCollection.
 * Input: ArrayBuffer of buildings.zip containing buildings.shp/.dbf/.prj.
 * Output: [{ name:'buildings.geojson', collection:{ type:'FeatureCollection', features:[...] } }].
 * Invalid archives and missing .shp/.dbf pairs throw before conversion.
 */
export async function readShapefileZip(buffer) {
  const zip = await JSZip.loadAsync(buffer)
  const entries = Object.values(zip.files).filter((entry) => !entry.dir && !entry.name.startsWith('__MACOSX/'))
  const entriesByName = new Map(entries.map((entry) => [entry.name.toLowerCase(), entry]))
  const shapes = entries.filter((entry) => /\.shp$/i.test(entry.name))
  if (!shapes.length) throw new Error('ZIP must contain at least one .shp layer.')
  for (const entry of shapes) {
    if (!entriesByName.has(entry.name.replace(/\.shp$/i, '.dbf').toLowerCase())) {
      throw new Error(`Missing DBF table for ${entry.name}.`)
    }
  }
  const usedNames = new Set()
  return Promise.all(
    shapes.map(async (entry) => {
      const stem = entry.name.replace(/\.shp$/i, '')
      const baseName = stem.split(/[\\/]/).at(-1)
      let name = baseName + '.geojson'
      for (let suffix = 2; usedNames.has(name); suffix++) name = `${baseName}_${suffix}.geojson`
      usedNames.add(name)
      const read = async (extension, type) => entriesByName.get((stem + extension).toLowerCase())?.async(type)
      const [shape, table, projection, encoding] = await Promise.all([
        entry.async('uint8array'),
        read('.dbf', 'uint8array'),
        read('.prj', 'string'),
        read('.cpg', 'string'),
      ])
      // shpjs ignores invalid PRJ text; validate it before claiming WGS84 output.
      if (projection != null) {
        if (!projection.trim()) throw new Error(`Empty projection definition for ${entry.name}.`)
        proj4(projection)
      }
      const collection = await shp({ shp: shape, dbf: table, prj: projection, cpg: encoding })
      if (collection?.type !== 'FeatureCollection' || !Array.isArray(collection.features)) {
        throw new Error('Archive contains an invalid GeoJSON layer.')
      }
      const dbfView = new DataView(table.buffer, table.byteOffset, table.byteLength)
      if (dbfView.getUint32(4, true) !== collection.features.length)
        throw new Error(`SHP and DBF record counts differ for ${entry.name}.`)
      // Restore nullable logical/numeric cells that the DBF parser turns into false/NaN.
      const headerSize = dbfView.getUint16(8, true),
        recordSize = dbfView.getUint16(10, true)
      let fieldOffset = 1
      for (let offset = 32; offset < headerSize - 1; offset += 32) {
        const fieldName = new TextDecoder()
          .decode(table.subarray(offset, offset + 11))
          .replace(/\0.*$/, '')
          .trim()
        const type = String.fromCharCode(dbfView.getUint8(offset + 11)),
          length = dbfView.getUint8(offset + 16)
        if (type === 'L')
          collection.features.forEach((feature, index) => {
            const value = String.fromCharCode(dbfView.getUint8(headerSize + index * recordSize + fieldOffset))
            if (value === '?' || value === ' ') feature.properties[fieldName] = null
          })
        fieldOffset += length
      }
      collection.features.forEach((feature) =>
        Object.keys(feature.properties).forEach((key) => {
          if (typeof feature.properties[key] === 'number' && !Number.isFinite(feature.properties[key]))
            feature.properties[key] = null
        }),
      )
      coordEach(collection, (point) => {
        if (
          !Array.isArray(point) ||
          point.length < 2 ||
          !point.slice(0, 2).every(Number.isFinite) ||
          Math.abs(point[0]) > 180 ||
          Math.abs(point[1]) > 90
        ) {
          throw new Error(`Invalid WGS84 output for ${entry.name}; check the .prj file.`)
        }
      })
      return {
        name,
        collection: { ...collection, fileName: stem, crs: { type: 'name', properties: { name: 'EPSG:4326' } } },
      }
    }),
  )
}

/**
 * Copy GeoJSON properties and supply a zero-based idx only when it is absent.
 * Input: feature 0 with { name:'Office' }. Output: properties { idx:0, name:'Office' }.
 * Existing idx values and source objects are preserved.
 */
export function prepareShapefile(collection) {
  return {
    ...collection,
    features: collection.features.map((feature, index) => ({
      ...feature,
      properties: { idx: index, ...feature.properties },
    })),
  }
}

/**
 * Match CSV rows to indexed features and copy every CSV column, including its key.
 * Produce one output feature per row/feature match; repeated rows stay separate.
 * Input: headers ['id','h'], rows [['1','10'],['1','12']], feature properties { id:1 }.
 * Output: matchedRows:2 and two features with h:'10' and h:'12'; source is unchanged.
 */
export function joinShapefileCsv(csv, collection, csvColumn, property) {
  if (
    !Number.isInteger(csvColumn) ||
    csvColumn < 0 ||
    csvColumn >= csv.headers.length ||
    !collection.features.some((feature) => Object.hasOwn(feature.properties ?? {}, property))
  ) {
    throw new Error('Choose a CSV column and GeoJSON property to match.')
  }
  const index = new Map()
  for (const feature of collection.features) {
    const key = joinKey(feature.properties?.[property])
    if (key === null) continue
    if (!index.has(key)) index.set(key, [])
    index.get(key).push(feature)
  }
  const features = []
  let matchedRows = 0
  for (const row of csv.rows) {
    const targets = index.get(joinKey(row[csvColumn]))
    if (!targets) continue
    const values = Object.fromEntries(csv.headers.map((header, column) => [header, row[column]]))
    for (const feature of targets) features.push({ ...feature, properties: { ...feature.properties, ...values } })
    matchedRows++
  }
  return { collection: { type: 'FeatureCollection', features }, matchedRows }
}

/**
 * Build a DBF table with an explicit schema: compatible scalar columns keep their
 * type, mixed/object columns become text (objects use JSON). UTF-8 bytes are written
 * as byte-valued characters because dbf writes one byte per JS character.
 * Reject colliding 10-byte names, non-ASCII field names and values over 254 UTF-8 bytes.
 * Input: [{ name:'Trường học', h:10.125, enabled:null }].
 * Output: a DBF DataView; .cpg='UTF-8' makes the name readable on import.
 */
function writeTable(rows) {
  const keys = [...new Set(rows.flatMap((row) => Object.keys(row)))]
  const names = new Set()
  const normalized = rows.map((row) => ({ ...row }))
  const meta = keys.map((name) => {
    const shortName = name.slice(0, 10).trim().toLowerCase()
    if (
      !name ||
      name !== name.trim() ||
      /[^\x20-\x7e]/.test(name) ||
      shortName === '__proto__' ||
      names.has(shortName)
    ) {
      throw new Error(`DBF field names must be ASCII and unique after 10-character truncation: ${name}.`)
    }
    names.add(shortName)
    const values = rows.map((row) => row[name]).filter((value) => value != null)
    const type =
      values.length && values.every((value) => typeof value === 'boolean')
        ? 'L'
        : values.length &&
            values.every(
              (value) =>
                typeof value === 'number' &&
                Number.isFinite(value) &&
                !/e/i.test(String(value)) &&
                String(value).length <= 18,
            )
          ? 'N'
          : 'C'
    let size = 1,
      decimals = 0
    for (const [index, row] of normalized.entries()) {
      const value = rows[index][name]
      if (type === 'C') {
        const text = value == null ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value)
        const bytes = new TextEncoder().encode(text)
        if (bytes.length > 254) throw new Error(`DBF value for ${name} exceeds 254 UTF-8 bytes.`)
        row[name] = String.fromCharCode(...bytes)
        size = Math.max(size, bytes.length)
      } else if (value != null) {
        size = Math.max(size, String(value).length)
        decimals = Math.max(decimals, String(value).split('.')[1]?.length ?? 0)
      }
    }
    return { name, type, size: type === 'L' ? 1 : size, decimals }
  })
  if (32 * meta.length + 33 > 65535 || meta.reduce((sum, field) => sum + field.size, 1) > 65535) {
    throw new Error('DBF table has too many columns or an oversized record.')
  }
  const table = dbf.structure(normalized, meta)
  meta.forEach((field, index) => {
    if (field.type === 'N') table.setUint8(32 + index * 32 + 17, field.decimals)
  })
  const recordSize = table.getUint16(10, true),
    headerSize = table.getUint16(8, true)
  rows.forEach((row, index) => {
    let offset = headerSize + index * recordSize + 1
    for (const field of meta) {
      if (field.type === 'L' && row[field.name] == null) table.setUint8(offset, 63)
      offset += field.size
    }
  })
  return table
}

/**
 * Group compatible geometry types into separate SHP layers and write one record
 * per feature. Normalize LineString to one multipart line; flatten MultiPolygon
 * rings while orienting outer rings clockwise and holes counter-clockwise.
 * Keep attributes in matching DBF row order and label text with UTF-8 .cpg files.
 * Input: two Point features with { name:'A' } and { name:'B' }.
 * Output: Promise<ArrayBuffer> ZIP containing shapes/mypoints.shp/.shx/.dbf/.prj/.cpg.
 * includeJoinedGeoJson=true also adds combinedGeoJSON_CSV.geojson to the ZIP.
 * The writer is 2D; elevation coordinates are rejected instead of silently removed.
 * Empty, unsupported, non-finite and unclosed geometry throws before writing.
 */
export async function writeShapefileZip(collection, includeJoinedGeoJson = false) {
  if (!collection.features.length) throw new Error('No features are available to export.')
  const groups = new Map()
  for (const feature of collection.features) {
    const geometry = feature.geometry
    const type = geometry?.type
    if (!['Point', 'LineString', 'MultiLineString', 'Polygon', 'MultiPolygon'].includes(type)) {
      throw new Error(`Unsupported Shapefile geometry: ${type ?? 'null'}.`)
    }
    coordEach(feature, (point) => {
      if (
        !Array.isArray(point) ||
        point.length < 2 ||
        !point.slice(0, 2).every(Number.isFinite) ||
        Math.abs(point[0]) > 180 ||
        Math.abs(point[1]) > 90
      )
        throw new Error('GeoJSON coordinates must be valid WGS84 longitude/latitude.')
      if (point.length > 2)
        throw new Error('Shapefile export supports 2D coordinates only; elevation coordinates cannot be preserved.')
    })
    let coordinates = geometry.coordinates
    let layer = 'mypoints',
      shapeType = 'POINT'
    if (type.includes('LineString')) {
      layer = 'mylines'
      shapeType = 'POLYLINE'
      coordinates = type === 'LineString' ? [coordinates] : coordinates
      if (!coordinates.length || coordinates.some((line) => line.length < 2))
        throw new Error('Lines must contain at least two coordinates.')
    } else if (type.includes('Polygon')) {
      layer = 'mypolygons'
      shapeType = 'POLYGON'
      const polygons = type === 'Polygon' ? [coordinates] : coordinates
      if (!polygons.length || polygons.some((polygon) => !polygon.length))
        throw new Error('Each polygon must contain rings.')
      coordinates = polygons.flatMap((polygon) =>
        polygon.map((ring, index) => {
          if (ring.length < 4 || ring[0][0] !== ring.at(-1)[0] || ring[0][1] !== ring.at(-1)[1]) {
            throw new Error('Polygon rings must be closed and contain at least four coordinates.')
          }
          const area = ring.reduce((sum, point, i) => {
            const next = ring[(i + 1) % ring.length]
            return (
              sum + (point[0] - ring[0][0]) * (next[1] - ring[0][1]) - (next[0] - ring[0][0]) * (point[1] - ring[0][1])
            )
          }, 0)
          if (!area) throw new Error('Polygon rings must enclose a non-zero area.')
          return (index === 0 ? area > 0 : area < 0) ? [...ring].reverse() : ring
        }),
      )
      if (!coordinates.length) throw new Error('Polygon geometry must contain rings.')
    } else if (coordinates.length < 2) throw new Error('Point geometry must contain longitude and latitude.')
    if (!groups.has(layer)) groups.set(layer, { type: shapeType, geometries: [], rows: [] })
    const group = groups.get(layer)
    group.geometries.push(coordinates)
    group.rows.push(feature.properties ?? {})
  }
  const zip = new JSZip(),
    folder = zip.folder('shapes')
  if (includeJoinedGeoJson) zip.file('combinedGeoJSON_CSV.geojson', JSON.stringify(collection))
  for (const [layer, group] of groups) {
    // Use the low-level writer: its ZIP helper groups separate lines into one record.
    const files = await new Promise((resolve, reject) =>
      write(
        group.rows.map(() => ({})),
        group.type,
        group.geometries,
        (error, output) => (error ? reject(error) : resolve(output)),
      ),
    )
    folder.file(layer + '.shp', files.shp.buffer)
    folder.file(layer + '.shx', files.shx.buffer)
    folder.file(layer + '.dbf', writeTable(group.rows).buffer)
    folder.file(layer + '.prj', files.prj)
    folder.file(layer + '.cpg', 'UTF-8')
  }
  return zip.generateAsync({ type: 'arraybuffer', compression: 'STORE' })
}
